                    f"三元组模式 {pattern_index} 中存在未知语句成分 {tok.value!r}",
                    tok.pos,
                )
            self._i += 1

        if not clauses:
            raise OntologyError(
                f"{'OPTIONAL' if optional else 'WHERE'} 花括号内的模式组为空"
                f"（字符位置 {lbrace_pos}）"
            )
