            if pending:
                finish_pattern()
            elif trailing_dot or not clauses:
                raise self._error(
                    "点号 '.' 只能出现在一条完整三元组模式或子句之后",
                    tok.pos,
                )
            trailing_dot = True
            self._i += 1
            continue

        # 子句关键字：结算尚未结束的三元组模式（子句边界不强制点号）。
